INSERT INTO eventos (code, name, pregunta, lugares, horarios, facilitador, demo, created_at) VALUES ('ACME01', 'Open Space de Experiencia Cliente de ACME', '¿Cómo hacemos para que cada persona que escribe a ACME sienta que alguien se hizo cargo?', '["Sala Roja","Sala Azul","Terraza"]', '["10:00","11:30","14:00"]', 'acme-demo-sin-acceso-0000', 1, '2026-10-20T09:00:00.000Z');
INSERT INTO sesiones (id, code, titulo, autor, tipo, lugar, hora, interes, token, estado, notas, decisiones, proximo_paso, at) VALUES
('ACME00001','ACME01','Reembolsos: que se vea en qué paso está cada uno','Diego','pregunta',0,0,9,'x','cerrada','Hoy un reembolso pasa por tres personas y nadie ve en qué paso está. Probamos dibujar el recorrido en la pared y aparecieron dos pasos que no sirven.','Armar un tablero simple con el paso de cada reembolso y repasarlo en la daily.','Diego y Lucía arman el tablero antes del 28 de noviembre.','2026-10-20T09:10:00.000Z'),
('ACME00002','ACME01','Guardias de fin de semana: ¿siempre las mismas cuatro personas?','Marta','ayuda',1,0,7,'x','cerrada','Se habló del cansancio y de lo difícil que es pedir ayuda cuando la cola está llena. Valeria contó cómo lo resolvían en su equipo anterior.','Rotar las guardias entre las 8 personas.','Marta arma el calendario rotativo hasta el 15 de diciembre.','2026-10-20T09:11:00.000Z'),
('ACME00003','ACME01','Avisos de lanzamiento: enterarnos antes de que lleguen las consultas','Valeria','pregunta',2,0,6,'x','cerrada','El último lanzamiento trajo 320 consultas en 48 horas y no teníamos guía de respuestas ni stock visible.','Pedir a Producto una nota 5 días antes de cada lanzamiento.','Valeria habla con Producto esta semana.','2026-10-20T09:12:00.000Z'),
('ACME00004','ACME01','Etiquetas automáticas que mandan mal los pedidos','Tomás','ayuda',0,1,5,'x','abierta','Revisando ejemplos de la semana pasada.','','','2026-10-20T09:13:00.000Z'),
('ACME00005','ACME01','Lo que nos funcionó: la guía de respuestas del lanzamiento de taladros','Camila','funciono',1,1,4,'x','propuesta','','','','2026-10-20T09:14:00.000Z'),
('ACME00006','ACME01','Responder rápido o resolver: ¿qué medimos?','Joaquín','pregunta',2,1,3,'x','propuesta','','','','2026-10-20T09:15:00.000Z'),
('ACME00007','ACME01','Cómo pedir ayuda cuando la cola está llena','Lucía','ayuda',0,2,2,'x','propuesta','','','','2026-10-20T09:16:00.000Z'),
